UPDATE DIAGNOSES d
SET diagnose_admission_id = (
    SELECT a.admission_id
    FROM ADMISSIONS a
    WHERE a.admission_patient_id = d.diagnose_patient_id
      AND TRUNC(a.admission_date) = TRUNC(d.diagnose_date)
);

COMMIT;
